def boxes(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; res=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]; hit=False
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=r+dr,c+dc
                            if (rr,cc) not in [(a,b) for a,b in cells] and g[rr][cc]==g[r][c]:
                                seen[rr][cc]=True; stack.append((rr,cc))
                vals={g[r][c] for r,c in cells}
                # closed-ish if it's a thick ring: bbox fill check
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                full = sum(1 for r in range(min(rs),max(rs)+1) for c in range(min(cs),max(cs)+1))
                res.append((vals,len(cells),full-sum(len([1 for x in cells])),min(rs),min(cs)))
    return res
